func (this *StyledTextRenderer) GetHeight() int32 {
	var defaultLineHeight int32 = this.GetLineHeight()
	if this.styledText.IsFixedLineHeight() {
		return this.lineCount*defaultLineHeight + this.styledText.topMargin + this.styledText.bottomMargin
	}
	var totalHeight int32 = 0
	var width int32 = this.styledText.GetWrapWidth()
	for i := int32(0); i < this.lineCount; i++ {
		var line *StyledTextRenderer_LineSizeInfo = this.GetLineSize(i)
		var height int32 = line.height
		if line.NeedsRecalculateHeight() {
			if width > 0 {
				var length int32 = jrt.StringLength(this.content.GetLine(i))
				height = ((length * this.averageCharWidth / width) + 1) * defaultLineHeight
			} else {
				height = defaultLineHeight
			}
		}
		totalHeight += height
	}
	return totalHeight + this.styledText.topMargin + this.styledText.bottomMargin
}

func (this *StyledTextRenderer) HasLink(offset int32) bool {
	if offset == -1 {
		return false
	}
	var lineIndex int32 = this.content.GetLineAtOffset(offset)
	var lineOffset int32 = this.content.GetOffsetAtLine(lineIndex)
	var line string = this.content.GetLine(lineIndex)
	var event *StyledTextEvent = this.styledText.GetLineStyleData(lineOffset, line)
	if event != (nil) {
		var styles []*StyleRange = event.styles
		if styles != (nil) {
			var ranges []int32 = event.ranges
			if ranges != (nil) {
				for i := int32(0); i < int32(len(ranges)); i += 2 {
					if ranges[i] <= offset && offset < ranges[i]+ranges[i+1] && styles[i>>1].Underline && styles[i>>1].UnderlineStyle == UNDERLINE_LINK {
						return true
					}
				}
			} else {
				for _, style := range styles {
					if style.Start <= offset && offset < style.Start+style.Length && style.Underline && style.UnderlineStyle == UNDERLINE_LINK {
						return true
					}
				}
			}
		}
	} else {
		if this.ranges != (nil) {
			var rangeCount int32 = this.styleCount << 1
			var index int32 = this.GetRangeIndex(offset, -1, rangeCount)
			if index >= rangeCount {
				return false
			}
			var rangeStart int32 = this.ranges[index]
			var rangeLength int32 = this.ranges[index+1]
			var rangeStyle *StyleRange = this.styles[index>>1]
			if rangeStart <= offset && offset < rangeStart+rangeLength && rangeStyle.Underline && rangeStyle.UnderlineStyle == UNDERLINE_LINK {
				return true
			}
		}
	}
	return false
}

